    rows(report({ householdUpkeep: { paidMilli, unpaidMilli } }), 'steward')
      .filter(row => row.label === 'Household upkeep');
  expect(charges(3000, 0)).toStrictEqual([{ label: 'Household upkeep', value: '3 Gold paid', tone: 'loss' }]);
